// 사용자 동의 설정 저장소 (쿠키를 사용)
function setConsent(consent) {
    document.cookie = `consent=${consent}; path=/; sameSite=strict; secure; expires=Fri, 31 Dec 9999 23:59:59 GMT;`;
}

// 현재 동의를 확인
function getConsent() {
    const cookie = document.cookie;
    const parts = cookie.split(';');
    for (let i = 0; i < parts.length; i++) {
        const [key, value] = parts[i].split('=');
        if (key.trim() === 'consent') {
            return value ? value : 'unknown';
        }
    }
    return 'unknown';
}

// 동의 팝업 표시 함수
function showConsentPopup() {
    const consent = getConsent();
    if (consent === 'unknown' || !isConsentGiven(consent)) {
        const popup = document.createElement('div');
        popup.id = 'consent-popup';
        popup.innerHTML = `
            <h2>사용자 동의</h2>
            <p>우리는 개인화된 경험을 제공하기 위해 쿠키를 사용합니다. 동의하지 않으시면 일부 기능이 제한될 수 있습니다.</p>
            <button id="accept-button">동의하기</button>
            <button id="reject-button">거절하기</button>
        `;
        document.body.appendChild(popup);

        const acceptButton = document.getElementById('accept-button');
        const rejectButton = document.getElementById('reject-button');

        acceptButton.addEventListener('click', () => {
            setConsent('accepted');
            hidePopup();
        });

        rejectButton.addEventListener('click', () => {
            setConsent('rejected');
            hidePopup();
        });
    }
}

